## 类型体操核心技巧


### 映射类型（Mapped Types）
```ts
// 遍历联合类型的每个成员
type Keys = 'a' | 'b' | 'c';
type Obj = { [K in Keys]: string }; // { a: string; b: string; c: string }

// 结合 keyof 遍历对象属性
type Readonly<T> = { readonly [K in keyof T]: T[K]; };
```

### 模板字面量类型（Template Literal Types）
```ts
type Greeting = `hello ${string}`;
type EventName = `on${Capitalize<'click' | 'change'>}`; // 'onClick' | 'onChange'

// 组合生成
type Color = 'red' | 'blue';
type Size = 'sm' | 'lg';
type ClassName = `${Color}-${Size}`; // 'red-sm' | 'red-lg' | 'blue-sm' | 'blue-lg'
```


### 递归类型
```ts
// 深度只读
type DeepReadonly<T> = {
    readonly [K in keyof T]: T[K] extends object ? DeepReadonly<T[K]> : T[K];
};

// 元组转联合
type TupleToUnion<T extends any[]> = T[number];
type U = TupleToUnion<[1, 2, 3]>; // 1 | 2 | 3
```


### 常用类型体操题
- DeepPartial：深层可选
- DeepReadonly：深层只读
- Flatten：数组展平
- LengthOfString：字符串长度
- ParseInt：字符串转数字

// DeepPartial
export type DeepPartial<T> = T extends object
  ? { [K in keyof T]?: DeepPartial<T[K]> }
  : T;

// DeepReadonly
type DeepReadonly<T> = {
  readonly [K in keyof T]: T[K] extends object ? DeepReadonly<T[K]> : T[K];
};

// 元组操作
type Head<T extends any[]> = T extends [infer H, ...any[]] ? H : never;
type Tail<T extends any[]> = T extends [any, ...infer R] ? R : never;
type Last<T extends any[]> = T extends [...any[], infer L] ? L : never;

// 字符串操作
type Capitalize<S extends string> = S extends `${infer H}${infer T}`
  ? `${Uppercase<H>}${T}`
  : S;

// 字符串转联合类型
type StringToUnion<S extends string> = S extends `${infer H}${infer T}`
  ? H | StringToUnion<T>
  : never;
type SU = StringToUnion<'hello'>; // 'h' | 'e' | 'l' | 'l' | 'o'

// 数字类型运算（通过元组长度）
type BuildTuple<N extends number, T extends any[] = []>
  = T['length'] extends N ? T : BuildTuple<N, [...T, any]>;

// 加法
type Add<A extends number, B extends number> =
  [...BuildTuple<A>, ...BuildTuple<B>]['length'] & number;
type Sum = Add<2, 3>; // 5

// Chainable Options（链式API类型）
type Chainable<T = {}> = {
  option<K extends string, V>(
    key: K extends keyof T ? never : K,
    value: V
  ): Chainable<T & Record<K, V>>;
  get(): T;
};

// 使用
const result = {}
  .option('name', 'hello')
  .option('age', 42)
  .get();
// type: { name: string; age: number }
